const stageNames=['Introduce gently','Build consistency','Try one small change','Comfortable · maintain'];
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}, dt=s=>new Date(s+'T12:00:00'), uid=()=>crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
let landingUrls=[];
let scheduleView=localStorage.getItem('clover-schedule-view-v2')||'day';
let day=today(), skills=await fetch('skills.json').then(r=>r.json()), page='today', db, cloud=null, user=null;
const req=indexedDB.open('clover-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('data',{keyPath:'id'});await new Promise((ok,no)=>{req.onsuccess=()=>{db=req.result;ok()};req.onerror=no});
const all=()=>new Promise((ok,no)=>{let r=db.transaction('data').objectStore('data').getAll();r.onsuccess=()=>ok(r.result);r.onerror=no});
const localPut=x=>new Promise((ok,no)=>{let t=db.transaction('data','readwrite');t.objectStore('data').put(x);t.oncomplete=ok;t.onerror=no});
let records=await all();
const get=id=>records.find(x=>x.id===id&&!x.deleted)?.value;
async function put(id,value,deleted=false){let x={id,value,deleted,updated:Date.now(),dirty:true};await localPut(x);records=await all();await sync();return x}
const list=prefix=>records.filter(x=>x.id.startsWith(prefix)&&!x.deleted).map(x=>({id:x.id,...x.value}));
let profile=()=>get('profile')||{name:'Clover',breed:'Australian labradoodle',birthday:'2026-09-13',home:'2026-11-07',sister:'10-year-old female goldendoodle',food:'Confirm breeder’s food and feeding amounts',meds:'None recorded',vet:'',emergency:'',groomer:'',notes:'Confirm pickup timing with breeder; November 7 is one day before 8 weeks.'};
function age(d=day){return Math.max(0,Math.round((dt(d)-dt(profile().birthday))/86400000))}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function modal(html){$('#modalbody').innerHTML=html;$('#modal').showModal()};$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
function form(title,fields,save){modal(`<h2>${title}</h2><form id="editor">${fields}<p id="error" role="alert"></p><button class="primary">Save</button></form>`);$('#editor').onsubmit=async e=>{e.preventDefault();let b=e.submitter;b.disabled=true;try{await save(new FormData(e.target));$('#modal').close();render()}catch(err){$('#error').textContent=err.message;b.disabled=false}}}
function input(name,label,value='',type='text',required=false){return `<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(value)}" ${required?'required':''}>`}
function skillView(id){let s=skills.find(s=>s.id===id),p=skillProgress(id),level=p.level;modal(`<span class="eyebrow">${s.category} · ${stageNames[level]}</span><h2>${s.title}</h2><p>1–3 minutes · ${level===0?'Quiet familiar place; make the first repetition very easy.':level===1?'Same quiet setting; build a few relaxed repetitions.':level===2?'Try one mild change: a new room, a little duration OR a distant distraction.':'Maintenance: a few easy repetitions; keep rewarding.'}</p><ol>${s.steps.split('|').map(x=>`<li>${x}</li>`).join('')}</ol><div class="notice">Success target: ${s.goal}<br>${p.last?.comfort==='overwhelmed'?'Last time was too much: reduce difficulty, give her space, and skip this session if she is still worried.':'Stop or simplify if her body becomes tense, she withdraws, or she cannot disengage.'}</div><p><button type="button" id="skill-boundaries" class="text-button">Need help stopping unwanted behaviour? ↗</button></p><p><strong>Progress:</strong> ${stageNames[level]} · ${p.wins}/3 comfortable success days at this step.</p><form id="practiceform"><label for="comfort">How comfortable was she?</label><select id="comfort" name="comfort"><option value="comfortable">Comfortable and engaged</option><option value="help">Needed help / not consistent yet</option><option value="overwhelmed">Worried or overwhelmed — stopped</option></select><label><input class="inlinecheck" type="checkbox" name="goal"> Met the success target at this step</label>${input('note','What worked / what was difficult')}<p class="muted">Three comfortable success days move her to the next step. Needing help repeats the step; worry steps back. This is a training rule of thumb, not a validated assessment.</p><button class="primary">Save practice & update plan</button></form>`);$('#skill-boundaries').onclick=()=>behaviourGuide(id);$('#practiceform').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);await put('practice:'+uid(),{skill:id,date:day,at:Date.now(),comfort:f.get('comfort'),goal:f.has('goal'),note:f.get('note')});$('#modal').close();render();toast('Practice saved. Her next suggestions now reflect this session.')}}

let base=[['07:30','Wake up & toilet','Straight to her toilet spot; reward after she finishes.','potty'],['07:45','Breakfast in her downstairs pen','Serve her measured meal in the pen, separately from her sister. Keep the attached crate open; fresh water available.','pen'],['08:00','Toilet & gentle play','Try again after breakfast. Keep play short and puppy-led.','potty'],['08:20','A tiny training moment','Five easy repetitions, then stop.','name'],['08:30','Settle while I work upstairs','Toilet first, then supervised access to the puppy-proofed bedroom. Offer a floor mat or bed; use a smaller gated area if work prevents close supervision.','room'],['10:00','Wake, toilet & discover','Toilet as soon as she wakes. One calm new experience.','sound'],['10:30','Rest & big-sister time','Separate rest areas; give your older dog individual attention.','senior'],['12:00','Lunch in her pen & toilet','Feed separately in the downstairs pen with the crate open. Offer a toilet trip after eating; meal times and amounts follow breeder/vet guidance.','pen'],['12:30','Mat practice','Reward a few seconds of calm on her portable mat.','mat'],['13:00','Downstairs pen & open-crate rest','Toilet first. Stay nearby while she learns to settle in the pen. Leave the crate open as a voluntary nap spot; let her sleep and toilet when she wakes.','pen'],['15:00','Wake, toilet & explore','Choose a safe, low-traffic exposure; end while comfortable.','sound'],['15:30','Handling & rest','One gentle brush stroke, reward, then a nap.','handling'],['17:30','Dinner in her pen & toilet','Measured dinner in the downstairs pen, separately from her sister. Crate open, water available, then a toilet opportunity.','pen'],['18:15','Family time','Supervised time with her sister, separate before pestering.','senior'],['19:00','Downstairs pen time together','Offer a safe chew or open-crate rest while you are downstairs. Meet toilet and social needs first; reduce difficulty if she is worried.','pen'],['20:30','Wind down','Low-key play, gentle handling; no forced exercise.','handling'],['22:00','Last toilet & into bed together','Toilet before joining your bed. Prevent falls or unsupervised jumping; keep bedding clear of entrapment risks. Respond to waking or restlessness with an overnight toilet trip.','bedtime']];

function routineForHome(){let stored=get('routine');if(!stored)return base;const oldNotes={
'Use the breeder/vet’s measured portion. Fresh water available.':'07:45',
'Safe pen or crate near you; toilet first. Let her sleep.':'08:30',
'Measured meal; toilet after eating. Adjust meal times with your vet.':'12:00',
'Keep a flexible rhythm: toilet whenever she wakes.':'13:00',
'Measured dinner, water and a calm toilet opportunity.':'17:30',
'Quiet space away from the bustle; allow uninterrupted rest.':'19:00',
'Sleeping space close by. Respond to overnight toilet needs.':'22:00'};return stored.map(row=>{let match=oldNotes[row[2]],replacement=match&&base.find(x=>x[0]===match);return replacement?[row[0],replacement[1],replacement[2],replacement[3]]:row})}
function tasks(){if(day<profile().home)return [...preparationTasks(),...careTasks(),...list('task:').filter(x=>x.date===day||x.repeat)].sort((a,b)=>a.time.localeCompare(b.time));let custom=routineForHome();let arr=custom.map((x,i)=>({id:'base'+i,time:x[0],title:x[1],notes:x[2],skill:x[3]}));let plan=trainingPlan();if(plan[0]){let slot=arr.find(t=>t.time==='08:20');if(slot)Object.assign(slot,{id:'train-am:'+plan[0].id+':'+skillProgress(plan[0].id).level,title:plan[0].title,notes:plan[0].reason,skill:plan[0].id});else arr.push({id:'train-am',time:'08:20',title:plan[0].title,notes:plan[0].reason,skill:plan[0].id})}if(plan[1])arr.push({id:'train-pm:'+plan[1].id+':'+skillProgress(plan[1].id).level,time:'16:00',title:plan[1].title,notes:plan[1].reason,skill:plan[1].id});arr.push(...careTasks(),...list('task:').filter(x=>x.date===day||x.repeat).map(x=>({...x})));return arr.sort((a,b)=>a.time.localeCompare(b.time))}
function nav(){document.querySelector('nav').innerHTML=[['today','home'],['skills','skills'],['memories','memories'],['profile','profile']].map(([id,n])=>`<a href="#${id}" class="${page===id?'active':''}">${n}</a>`).join('');$('#age').textContent=`${profile().name} · ${Math.floor(age()/7)} weeks, ${age()%7} days old`}
function render(){page=location.hash.slice(1)||'today';document.body.dataset.page=page;nav();let app=$('#app');if(page==='today'){let ts=tasks(),done=ts.filter(t=>(t.completed||get(doneKey(t.id)))).length;app.innerHTML=`${landingMarkup()}<section id="daily-schedule"><div class="pagehead"><h1>${dt(day).toLocaleDateString('en-CA',{month:'long',day:'numeric'}).toLowerCase()}</h1><span class="schedule-age">${Math.floor(age()/7)} weeks old</span></div><div class="toolbar"><div class="view-toggle"><button data-view="day" class="${scheduleView==='day'?'selected':''}">Day</button><button data-view="week" class="${scheduleView==='week'?'selected':''}">Week</button></div><input type="date" id="date" value="${day}" aria-label="Schedule date"><button id="addtask">+ Task</button><details class="more-actions"><summary>More</summary><div><button id="addcaretask">Schedule care</button><button id="routine">Edit daily routine</button><button id="quicklog">Toilet / sleep log</button></div></details></div>${day<profile().home?'<div class="notice">Before she arrives — preparation checklist</div>':''}<p class="muted">${done} of ${ts.length} complete</p><div class="${scheduleView==='week'?'week-active':''}"><div class="day-view"><div class="day-layout"><div class="schedule"><div class="schedule-heading"><span>TASK</span><span>NOTES</span></div>${ts.map(t=>`<div class="task ${(t.completed||get(doneKey(t.id)))?'done':''} ${currentTask(ts)===t.id?'current':''}"><button class="complete-dot" aria-label="Complete ${esc(t.title)}" aria-pressed="${!!(t.completed||get(doneKey(t.id)))}" data-done="${t.id}">${(t.completed||get(doneKey(t.id)))?'✓':'·'}</button><time>${displayTime(t.time)}</time><div class="description"><span class="title">${t.skill?`<button class="task-title-button" data-skill="${t.skill}">${esc(t.title)}</button>`:esc(t.title)}</span>${t.skill?`<button class="skilllink" data-skill="${t.skill}">how to ↗</button>`:''}</div><div class="tasknotes">${esc(t.notes)}${t.careId?`<button class="edit-task" data-care-move="${t.careId}">Reschedule</button>`:t.completed?'':`<button class="edit-task" data-edit="${t.id}" aria-label="Edit ${esc(t.title)}">edit</button>`}</div></div>`).join('')}</div></div></div><div class="week-view">${scheduleView==='week'?weekCalendar():''}</div></div><details class="daily-details"><summary>Care reminders & daily log</summary><div class="cards bottomcards"><section class="card"><h3>Care reminders</h3>${reminders()}</section><section class="card"><h3>Daily log</h3>${list('log:').filter(x=>x.date===day).map(x=>`<p>${esc(x.time)} · ${esc(x.kind)} · ${esc(x.note)}</p>`).join('')||'<p class="muted">Log toilet trips and naps to learn her patterns.</p>'}</section></div></details></section>`;hydrateLanding();$('#add-landing-photos').onclick=()=>addMemoryForm(true);$('#manage-landing').onclick=()=>{location.hash='memories'};$('#to-schedule').onclick=e=>{e.preventDefault();$('#daily-schedule').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>{scheduleView=e.dataset.view;localStorage.setItem('clover-schedule-view-v2',scheduleView);render()});document.querySelectorAll('[data-prepday]').forEach(e=>e.onclick=()=>{day=e.dataset.prepday;scheduleView='day';localStorage.setItem('clover-schedule-view-v2','day');render()});document.querySelectorAll('[data-event]').forEach(e=>e.onclick=()=>calendarDetail(e.dataset.eventdate,e.dataset.event));document.querySelectorAll('[data-day]').forEach(e=>e.onclick=()=>{day=e.dataset.day;render()});$('#date').onchange=e=>{day=e.target.value||today();render()};$('#addtask').onclick=()=>editTask();$('#routine').onclick=editRoutine;$('#addcaretask').onclick=scheduleCare;$('#quicklog').onclick=logForm;document.querySelectorAll('[data-done]').forEach(el=>el.onclick=async()=>{let t=ts.find(x=>x.id===el.dataset.done);if(t?.completed)return;if(t?.careId){completeCare(t.careId);return}await put(doneKey(el.dataset.done),!get(doneKey(el.dataset.done)));render()});document.querySelectorAll('[data-care-move]').forEach(e=>e.onclick=()=>postponeCare(e.dataset.careMove));document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>editTask(ts.find(t=>t.id===el.dataset.edit)))}
else if(page==='skills'){app.innerHTML=`<span class="eyebrow">02 / the learning library</span><h1>skills</h1><p class="intro">Grouped by when to introduce each skill. These are suggested starting windows; Clover’s comfort and earlier learning decide the pace.</p><p class="boundary-link"><button id="behaviourguide">Stopping unwanted behaviour ↗</button></p><div class="toolbar"><input id="search" placeholder="Find sit, crate training, puppy biting…" aria-label="Search skills"><select id="filter"><option value="">All categories</option>${[...new Set(skills.map(x=>x.category))].map(x=>`<option>${x}</option>`).join('')}</select></div><p class="outing-link"><a href="#outings">Outing preparation ↗</a></p><div id="skillcards"></div>`;let paint=()=>{let results=skills.filter(s=>(s.title+' '+s.steps+' '+s.category).toLowerCase().includes($('#search').value.toLowerCase())&&(!$('#filter').value||s.category===$('#filter').value)).sort((a,b)=>a.week-b.week||a.title.localeCompare(b.title));let bands=[{min:8,max:8,label:'Around 8 weeks',note:'Her first foundations · tiny, gentle introductions'},{min:9,max:10,label:'Around 9–10 weeks',note:'Everyday manners, care and discovering the world'},{min:11,max:12,label:'Around 11–12 weeks',note:'Build on familiar foundations'},{min:13,max:16,label:'Around 13–16 weeks',note:'Small new settings and distractions, when ready'},{min:17,max:100,label:'Around 6 months & beyond',note:'Refresh, maintain and keep having fun'}];$('#skillcards').innerHTML=bands.map(b=>{let items=results.filter(x=>x.week>=b.min&&x.week<=b.max);return items.length?`<details class="age-section" ${b.min===8||$('#search').value||$('#filter').value?'open':''}><summary class="age-heading"><span class="age-dot">${b.min===17?'24':String(b.min).padStart(2,'0')}</span><div><h2>${b.label}</h2><p>${b.note}</p></div><span class="age-count">${items.length} ${items.length===1?'skill':'skills'}</span></summary><div class="cards">${items.map(s=>`<article class="card skill-card"><div class="skill-meta"><span class="tag">${s.category}</span><span class="muted">${s.week}+ weeks</span></div><h3>${s.title}</h3><p>${s.goal}</p><small>${stageNames[skillProgress(s.id).level]} · ${list('practice:').filter(x=>x.skill===s.id).length} practices${s.week>age()/7?' · for later':''}</small><p><button data-skill="${s.id}">Open practice ↗</button></p></article>`).join('')}</div></details>`:''}).join('')||'<p class="empty-note">No skills match that search. Try a different word or category.</p>';bindSkills()};$('#search').oninput=paint;$('#filter').onchange=paint;$('#behaviourguide').onclick=()=>behaviourGuide();paint()}
else if(page==='outings'){let stages=[['Home base','mat','A relaxed mat, safe separation, toilet patterns and easy handling.'],['Travel rehearsal','car','Stationary car → engine → short ride. Add duration only when comfortable.'],['Quiet office · Scarborough','office','Permission, quiet desk, portable mat, short visit, easy exit.'],['City practice','lift','Quiet elevator and distant traffic before busy downtown entrances.'],['Coworking · downtown','cowork','Off-peak 5–10 minute visit; build gradually over successful days.']];app.innerHTML=`<span class="eyebrow">03 / a little more, when she’s ready</span><h1>goals</h1><p class="intro">Home, everyday skills, care and outings. Choose what to work on.</p><div class="cards">${[["Home & independence","crate","Feel safe resting and spending short periods apart."],["Everyday manners","sit","Build sit, down, recall and kind greetings."],["Her big sister","senior","Protect rest, space and calm companionship."],["Care confidence","handling","Make brushing, handling and vet visits comfortable."]].map(g=>`<section class="card"><h3>${g[0]}</h3><p>${g[2]}</p><button data-skill="${g[1]}">Practice guide ↗</button></section>`).join('')}</div><h2>One goal: outings & workdays</h2><div class="notice">Ask your vet which locations are safe before vaccine completion. Confirm each workplace’s pet rules. Leave if she freezes, hides, repeatedly yawns or cannot disengage; do not force greetings.</div><div class="cards">${stages.map((s,i)=>`<article class="card"><span class="tag">0${i+1}</span><h3>${s[0]}</h3><p>${s[2]}</p><button data-skill="${s[1]}">Practice guide ↗</button><label><input class="inlinecheck" type="checkbox" data-stage="${i}" ${get('stage:'+i)?'checked':''}> Comfortable at this stage</label></article>`).join('')}</div><section class="card"><h3>Pack the little things</h3><p>Harness & lead · ID tag · portable mat · water & bowl · tiny treats · food · waste bags · towels · safe chew · vet contact · backup care plan.</p><button id="outinglog">+ Log an outing</button>${list('outing:').sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<p>${esc(x.date)} · ${esc(x.place)} · ${esc(x.notes)}</p>`).join('')}</section>`;document.querySelectorAll('[data-stage]').forEach(e=>e.onchange=()=>put('stage:'+e.dataset.stage,e.checked));$('#outinglog').onclick=()=>form('A little adventure',input('date','Date',day,'date',true)+input('place','Place','','text',true)+input('notes','Comfort, duration, next easier step'),async f=>put('outing:'+uid(),Object.fromEntries(f)))}
else if(page==='memories'){renderAlbum()}
else if(page==='profile')profilePage();else if(page==='sources')sources();else{location.hash='today'}bindSkills()}
function bindSkills(){document.querySelectorAll('[data-skill]').forEach(e=>e.onclick=()=>skillView(e.dataset.skill))}
function editRoutine(){form('Your daily rhythm','<p>Edit the reusable routine: time | task | notes | skill ID. This changes the template for all dates. Keep the four columns on each line.</p><textarea name="lines" rows="18">'+esc((routineForHome()).map(x=>x.join(' | ')).join('\n'))+'</textarea>',async f=>{let rows=f.get('lines').split('\n').filter(x=>x.trim()).map(x=>x.split('|').map(x=>x.trim()));if(rows.some(r=>r.length!==4||!/^([01]\d|2[0-3]):[0-5]\d$/.test(r[0])||(r[3]&&!skills.some(s=>s.id===r[3]))))throw Error('Each line needs HH:MM | task | notes | valid skill ID (or blank).');await put('routine',rows)})}
function editTask(t){form(t?'Edit task':'Add a task',input('time','Time',t?.time||'09:00','time',true)+input('title','Task',t?.title||'','text',true)+input('notes','Specific notes',t?.notes||'')+`<label>Quick guide</label><select name="skill"><option value="">None</option>${skills.map(s=>`<option value="${s.id}" ${s.id===t?.skill?'selected':''}>${s.title}</option>`).join('')}</select>`+(t&&!t.id.startsWith('task:')?'<p>Edits to a template task apply to every day. Use “Add a task” for a one-day change.</p>':'<label><input class="inlinecheck" type="checkbox" name="repeat" '+(t?.repeat?'checked':'')+'> Repeat daily</label>'),async f=>{let v=Object.fromEntries(f);if(t?.careId){throw Error('Use Reschedule on the care task to move its date.')}else if(t?.id.startsWith('prep')){await put('prep-edit:'+t.id,v)}else if(t?.id.startsWith('base')){let rows=structuredClone(routineForHome());rows[Number(t.id.slice(4))]=[v.time,v.title,v.notes,v.skill];await put('routine',rows)}else if(t?.id==='milestone'||t?.id.startsWith('train-')){throw Error('This suggestion is automatic. Add a custom task or edit the daily routine instead.')}else await put(t?.id||'task:'+uid(),{...v,date:day,repeat:f.has('repeat')})})}
function logForm(){form('Learn her rhythm',input('time','Time',new Date().toTimeString().slice(0,5),'time',true)+'<label>Type</label><select name="kind"><option>Pee outside</option><option>Poop outside</option><option>Accident</option><option>Nap started</option><option>Woke up</option><option>Meal</option></select>'+input('note','Notes'),async f=>put('log:'+uid(),{...Object.fromEntries(f),date:day}))}
function reminders(){return list('care:').filter(x=>x.next).sort((a,b)=>a.next.localeCompare(b.next)).slice(0,6).map(x=>`<p><strong>${esc(x.title)}</strong><br><small>${esc(x.next)} · ${esc(x.kind)} ${x.next<today()?'· overdue':''}</small></p>`).join('')||'<p class="muted">Add vet, vaccine, grooming and bath reminders in Profile.</p>'}
function profilePage(){let p=profile(),exp=list('expense:'),month=today().slice(0,7),spent=exp.filter(x=>x.date.startsWith(month)).reduce((a,x)=>a+Number(x.amount),0);$('#app').innerHTML=`<span class="eyebrow">05 / profile</span><h1>${esc(p.name)}</h1><p class="intro">${esc(p.breed)} · Born ${esc(p.birthday)} · Home ${esc(p.home)}</p><div class="grid"><div><section class="card"><span class="eyebrow">home setup</span><h3>Home setup</h3><p><strong>Nighttime</strong><br>Sleeping in your bed, with safe access and overnight toilet support.</p><p><strong>Working upstairs</strong><br>Supervised freedom in your puppy-proofed bedroom. Start with a manageable area; use a gate when focused work means you cannot watch her.</p><p><strong>Downstairs</strong><br>Meals and relaxed time in her pen, with an open crate available as a voluntary rest spot. Feed the dogs separately.</p><p class="muted">Crate comfort remains useful for travel, grooming or vet care. Closed-door practice is brief and gradual; it is separate from her bed-sharing plan.</p></section><section class="card"><h3>The essentials</h3><p><strong>Food</strong><br>${esc(p.food)}</p><p><strong>Medications & instructions from vet</strong><br>${esc(p.meds)}</p><p><strong>Her big sister</strong><br>${esc(p.sister)}</p><p><strong>Vet</strong> ${esc(p.vet)||'Add contact'}<br><strong>Emergency clinic</strong> ${esc(p.emergency)||'Add contact'}<br><strong>Groomer</strong> ${esc(p.groomer)||'Add contact'}</p><p>${esc(p.notes)}</p><button id="editprofile">Edit profile</button></section><section class="card"><h3>Care & medical records</h3><p class="muted">Record confirmed vaccines and vet-set due dates. Grooming and bath intervals depend on coat, skin and groomer guidance.</p><button id="addcare">+ Add record / reminder</button>${list('care:').sort((a,b)=>(a.next||'9999').localeCompare(b.next||'9999')).map(x=>`<p><span class="tag">${esc(x.kind)}</span> <strong>${esc(x.title)}</strong><br>Last: ${esc(x.date)||'Not recorded'} · Next: ${esc(x.next)||'Not set'}<br>${esc(x.notes)}<br><button data-care="${x.id}">Edit / reschedule</button></p>`).join('')}</section></div><div><section class="card"><h3>The puppy budget</h3><span class="eyebrow">${month} · CAD</span><div class="stats"><div><strong>$${spent.toFixed(2)}</strong>spent</div><div><strong>$${Number(get('budget')||0).toFixed(0)}</strong>monthly plan</div></div><p>${get('budget')?'Remaining: $'+(Number(get('budget'))-spent).toFixed(2):'Set your own monthly allowance.'}</p><button id="budget">Set budget</button> <button id="expense">+ Expense</button>${exp.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<p>${esc(x.date)} · ${esc(x.category)}<br>${esc(x.note)} · $${Number(x.amount).toFixed(2)}</p>`).join('')}</section><section class="card"><h3>Coming up</h3>${reminders()}</section><section class="card"><h3>Weight diary</h3><button id="weight">+ Record weight</button>${list('weight:').sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<p>${esc(x.date)} · ${esc(x.kg)} kg</p>`).join('')}</section></div></div>`;$('#editprofile').onclick=()=>form('Clover’s profile',Object.entries(p).map(([k,v])=>input(k,({home:'Homecoming',birthday:'Birthday',meds:'Medications (vet instructions only)',notes:'Notes / allergies / microchip'}[k]||k),v,['birthday','home'].includes(k)?'date':'text',true)).join(''),async f=>put('profile',Object.fromEntries(f)));function care(id){let x=id?get(id):{};form('Care record',`<label>Type</label><select name="kind">${['Vaccine','Vet','Grooming appointment','Bath','Medication review','Parasite prevention','Other'].map(k=>`<option ${k===x.kind?'selected':''}>${k}</option>`).join('')}</select>`+input('title','Name',x.title||'','text',true)+input('date','Completed date',x.date||'','date')+input('next','Next due / book date',x.next||'','date')+input('time','Schedule time',x.time||'18:00','time')+input('interval','Repeat every N days (optional)',x.interval||'','number')+input('notes','Notes / vet instructions',x.notes||''),async f=>{let v=Object.fromEntries(f);if(v.interval&&(Number(v.interval)<1||!Number.isInteger(Number(v.interval))))throw Error('Repeat interval must be a whole number of days.');await put(id||'care:'+uid(),{...x,...v})})}$('#addcare').onclick=()=>care();document.querySelectorAll('[data-care]').forEach(e=>e.onclick=()=>care(e.dataset.care));$('#budget').onclick=()=>form('Monthly budget (CAD)',input('amount','Amount',get('budget')||'','number',true),async f=>{if(Number(f.get('amount'))<0)throw Error('Use a positive amount.');await put('budget',Number(f.get('amount')))});$('#expense').onclick=()=>form('Add expense',input('date','Date',today(),'date',true)+input('category','Category','Food','text',true)+input('amount','Amount (CAD)','','number',true)+input('note','Notes'),async f=>{if(Number(f.get('amount'))<0)throw Error('Use a positive amount.');await put('expense:'+uid(),Object.fromEntries(f))});$('#weight').onclick=()=>form('Weight diary',input('date','Date',today(),'date',true)+input('kg','Weight (kg)','','number',true),async f=>{if(Number(f.get('kg'))<=0)throw Error('Enter a positive weight.');await put('weight:'+uid(),Object.fromEntries(f))})}
function sources(){$('#app').innerHTML=`<h1>gentle, informed care</h1><section class="card"><p>The routines and short exercises are practical starting templates, not individualized veterinary advice. Adjust meals, toilet frequency, sleep and activity to Clover. Readiness takes priority over age. No automatic medication doses or vaccine dates are prescribed.</p><p><a href="https://avsab.org/resources/position-statements/">AVSAB: humane training & puppy socialization</a></p><p><a href="https://www.akc.org/expert-advice/puppy-information/introducing-puppies-to-senior-dogs/">AKC: introducing puppies to senior dogs</a></p><p><a href="https://vcahospitals.com/pediatric/puppy/behavior-training/when-to-start-puppy-training-classes">VCA: puppy training milestones</a></p><p>Sources reviewed October 31, 2026. App care reminders appear here when opened; there are no background push notifications.</p></section>`}
// IndexedDB keeps media separate from structured records; export includes both.
const mr=indexedDB.open('clover-media',1);mr.onupgradeneeded=()=>mr.result.createObjectStore('files');const mdb=await new Promise((ok,no)=>{mr.onsuccess=()=>ok(mr.result);mr.onerror=no});
const mediaLocal=(method,key,val)=>new Promise((ok,no)=>{let t=mdb.transaction('files',method==='get'?'readonly':'readwrite'),r=t.objectStore('files')[method](...(method==='put'?[val,key]:[key]));r.onsuccess=()=>ok(r.result);r.onerror=no});
async function mediaPut(id,file){await mediaLocal('put',id,file);if(cloud&&user){let {error}=await cloud.storage.from('memories').upload(user.id+'/'+id,file,{contentType:file.type});if(error)throw error}}
async function mediaGet(id){let b=await mediaLocal('get',id);if(b)return b;if(!cloud||!user)throw Error('Sign in to download this attachment.');let {data,error}=await cloud.storage.from('memories').download(user.id+'/'+id);if(error)throw error;await mediaLocal('put',id,data);return data}
async function mediaDelete(id){if(cloud&&user){let{error}=await cloud.storage.from('memories').remove([user.id+'/'+id]);if(error)throw error}await mediaLocal('delete',id)}
let syncing=false;
async function sync(){if(!cloud||!user||syncing)return;syncing=true;try{let dirty=records.filter(x=>x.dirty);for(let x of dirty){if(x.id.startsWith('memory:')&&x.value?.file){let file=await mediaLocal('get',x.value.file);if(file){let r=await cloud.storage.from('memories').upload(user.id+'/'+x.value.file,file,{upsert:true,contentType:file.type});if(r.error)throw r.error}}let {error}=await cloud.from('clover_records').upsert({owner:user.id,id:x.id,value:x.value,deleted:x.deleted,updated:x.updated});if(error)throw error;await localPut({...x,dirty:false})}let{data,error}=await cloud.from('clover_records').select('*');if(error)throw error;let current=await all();for(let x of data){let here=current.find(r=>r.id===x.id);if(!here||(!here.dirty&&x.updated>=here.updated))await localPut({id:x.id,value:x.value,deleted:x.deleted,updated:x.updated,dirty:false})}records=await all();$('#account').textContent='☘ Synced · connection'}catch(e){toast('Saved on this device. Sync failed: '+e.message);$('#account').textContent='☘ Local changes · retry sync'}finally{syncing=false}}
async function connect(){let cfg=JSON.parse(localStorage.getItem('clover-config')||'null');if(!cfg)return;let{createClient}=await import('https://esm.sh/@supabase/supabase-js@2');cloud=createClient(cfg.url,cfg.key);let{data,error}=await cloud.auth.getSession();if(error)throw error;user=data.session?.user;if(user){let bound=localStorage.getItem('clover-owner');if(bound&&bound!==user.id){await cloud.auth.signOut();user=null;throw Error('This browser is linked to another account. Use a separate browser profile.')}localStorage.setItem('clover-owner',user.id);await sync()}cloud.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT')user=null});}
$('#account').onclick=()=>{modal(`<h2>Connected, wherever you are.</h2><p>${user?'Signed in as '+esc(user.email):'Local mode: data stays in this browser until you configure sync and sign in.'}</p><p>Follow SETUP.md to create your private backend. Use the same account on both devices. Sync checks every 30 seconds while open.</p><form id="connection">${input('url','Supabase project URL',JSON.parse(localStorage.getItem('clover-config')||'{}').url||'','url',true)}${input('key','Publishable / anon key',JSON.parse(localStorage.getItem('clover-config')||'{}').key||'','text',true)}${input('email','Email',user?.email||'','email',true)}${input('password','Password (minimum 8 characters)','','password',true)}<button name="action" value="login">Sign in</button> <button name="action" value="signup">Create account</button><p id="authmessage"></p></form><p><button id="sync">Sync now</button> <button id="logout">Sign out</button></p><hr><h3>Keep a backup</h3><p>Export includes records and locally available media. Sync first, and open memories to download any attachments saved on another device before exporting.</p><button id="export">Export backup</button><label>Restore backup (merges by record ID)</label><input id="import" type="file" accept="application/json">`);$('#connection').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);try{localStorage.setItem('clover-config',JSON.stringify({url:f.get('url'),key:f.get('key')}));await connect();let args={email:f.get('email'),password:f.get('password')};if(args.password.length<8)throw Error('Use at least 8 characters.');let r=e.submitter.value==='signup'?await cloud.auth.signUp(args):await cloud.auth.signInWithPassword(args);if(r.error)throw r.error;$('#authmessage').textContent=r.data.session?'Signed in. Close to continue.':'Check your email to confirm your account, then sign in.';if(r.data.session){user=r.data.user;let bound=localStorage.getItem('clover-owner');if(bound&&bound!==user.id){await cloud.auth.signOut();user=null;throw Error('Use a separate browser profile for another account.')}localStorage.setItem('clover-owner',user.id);await sync();render()}}catch(e){$('#authmessage').textContent=e.message}};$('#sync').onclick=async()=>{await sync();render()};$('#logout').onclick=async()=>{if(cloud)await cloud.auth.signOut();user=null;$('#account').textContent='☘ Local mode';toast('Signed out. Local data remains on this device.');$('#modal').close()};$('#export').onclick=async()=>{let media={};for(let m of list('memory:'))if(m.file){let b=await mediaLocal('get',m.file);if(b)media[m.file]=await new Promise(ok=>{let r=new FileReader();r.onload=()=>ok(r.result);r.readAsDataURL(b)})}let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:1,records,media})],{type:'application/json'}));a.download='clover-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#import').onchange=async e=>{try{let v=JSON.parse(await e.target.files[0].text());if(v.version!==1||!Array.isArray(v.records))throw Error('Invalid backup');for(let [id,url]of Object.entries(v.media||{})){if(!url.startsWith('data:'))throw Error('Invalid attachment');await mediaLocal('put',id,await fetch(url).then(r=>r.blob()))}for(let x of v.records){if(typeof x.id!=='string'||typeof x.updated!=='number')throw Error('Invalid record');await localPut({...x,updated:Date.now(),dirty:true})}records=await all();await sync();render();toast('Backup restored')}catch(e){toast(e.message)}}};


function doneKey(id){return 'done:'+(id.startsWith('prep')?'preparation':day)+':'+id}
function currentTask(ts){if(day!==today()||day<profile().home)return null;let now=new Date().toTimeString().slice(0,5);return ts.filter(t=>t.time<=now).at(-1)?.id||null}
function preparationTasks(){return [
['Book her first vet visit','Ask the breeder for vaccine/deworming records. Confirm pickup timing, feeding and the first checkup.'],
['Prepare bed-sharing & the downstairs pen','Plan safe bed access and prevent falls or gaps. Puppy-proof the bedroom; downstairs, attach an open crate to a pen with water, room to rest and a separate feeding space.'],
['Puppy-proof every room','Secure cables, medications, bins, toxic plants and small swallowable items. Gate stairs and unsafe areas.'],
['Create her sister’s quiet zone','Set up a puppy-free bed and feeding area for your older dog. Arrange gates before Clover arrives.'],
['Collect food & feeding instructions','Get the exact breeder food, measured portions and current meal times. Plan changes with your vet.'],
['Pack the homecoming bag','Secure travel crate/restraint, towel, cleanup supplies, lead, harness, water and breeder contact.'],
['Choose a toilet spot','Decide where to take her immediately after arriving. Have treats and enzymatic cleaner ready.'],
['Find a reward-based puppy class','Ask about vaccine entry requirements, small groups, supervised play and gentle teaching.'],
['Plan the first week of company','Arrange time at home and backup care. Keep visitors and demands low; plan overnight toilet support.'],
['Get ID & emergency details ready','Arrange ID tag, microchip transfer, regular vet and emergency clinic contacts.'],
['Prepare grooming supplies','Soft brush, appropriate comb, puppy-safe shampoo and a non-slip surface. Ask a groomer about coat care.'],
['Agree on family routines','Choose cue words, feeding responsibility, toilet handoffs and a plan for calm dog introductions.']
].map((x,i)=>({id:'prep'+i,time:'',title:x[0],notes:x[1],...get('prep-edit:prep'+i),skill:['','','','senior','','car','potty','','alone','','handling',''][i]}))}
setInterval(()=>{if(page==='today'&&!$('#modal').open)render()},60000);


const prerequisites={sit:['marker'],down:['sit'],stand:['sit'],recall:['name'],lead:['collar'],car:['collar'],drop:['marker'],greet:['name'],lift:['watch'],office:['mat','car'],cowork:['office','lift'],stay:['sit'],leave:['marker'],release:['sit'],teeth:['handling'],nails:['handling'],ears:['handling'],bath:['handling'],dryer:['handling'],chin:['handling'],vet:['handling'],door:['collar'],uturn:['lead'],play:['drop'],fetch:['drop'],alonehome:['alone','pen'],distraction:['sit','recall'],teen:['distraction']};
const priority=['marker','name','crate','handling','pen','room','bedtime','alone','sit','touch','mat','bite','collar','down','recall','lead','drop','watch','people','surfaces','household','guard','jump','release','stand','teeth','nails','ears','chin','vet','car','bath','dryer','dogs','door','uturn','greet','stay','leave','counter','quiet','restrain','alonehome','find','play','sniffwalk','fetch','lift','office','cowork','distraction','teen'];
function skillProgress(id){let logs=list('practice:').filter(x=>x.skill===id&&x.date<=day&&x.comfort).sort((a,b)=>a.date.localeCompare(b.date)||(a.at||0)-(b.at||0)),level=0,days=new Set(),last=null;for(let x of logs){last=x;if(x.comfort==='overwhelmed'){level=Math.max(0,level-1);days.clear()}else if(x.comfort==='help'){days.clear()}else if(x.goal){days.add(x.date);if(days.size>=3&&level<3){level++;days.clear()}}}return {level,wins:Math.min(3,days.size),last}}
function trainingPlan(){let ready=priority.map(id=>skills.find(s=>s.id===id)).filter(Boolean).filter(s=>s.week<=Math.max(8,age()/7)&&(prerequisites[s.id]||[]).every(id=>skillProgress(id).level>=1));let ranked=ready.map((s,i)=>{let p=skillProgress(s.id),gap=p.last?Math.round((dt(day)-dt(p.last.date))/86400000):999;let due=p.level===3?gap>=7:gap>=1;let score=!due?-10000:p.last?.comfort==='overwhelmed'?150:p.last?.comfort==='help'?130:p.level>0&&p.level<3?100:!p.last?70:90;return {s,p,gap,score:score-i*.6}}).sort((a,b)=>b.score-a.score);return ranked.slice(0,2).map(({s,p,gap})=>({...s,title:s.title+' · '+stageNames[p.level].toLowerCase(),reason:p.last?.date===day?'Already practiced today — this is an optional easy repeat; stop while she is happy.':p.last?.comfort==='overwhelmed'?'Step back: try a much easier version only if she is comfortable; otherwise skip.':p.last?.comfort==='help'?'Repeat with more help in a quiet setting; no harder task yet.':p.level===3?'Maintenance check: keep this familiar skill fresh.':p.level>0?stageNames[p.level]+': '+p.wins+'/3 comfortable success days. '+s.goal:'Start gently: age-appropriate'+((prerequisites[s.id]||[]).length?' and earlier foundations are comfortable.':'; a useful early foundation.') }));}

function behaviourGuide(returnSkill){modal(`<span class="eyebrow">kind, clear boundaries</span><h2>Help her choose something better.</h2><p>You can stop access to an unwanted behaviour without shouting, frightening or hurting her. She still needs clear limits and help learning what to do.</p><ol><li><strong>Prevent it.</strong> Move shoes, clear counters, use a gate or supervise closely. Make the unwanted option harder to reach before it happens.</li><li><strong>Interrupt calmly and safely.</strong> Pause play, step away or guide her away with a familiar cue such as “touch” or “this way”. Avoid chasing, grabbing her muzzle or jerking the lead.</li><li><strong>Offer a useful alternative.</strong> Give her a chew, invite four paws on the floor, or guide her to a mat. Make the alternative easy enough to succeed.</li><li><strong>Reward that alternative.</strong> Mark and reward the moment she does it. Also catch the good behaviour before trouble starts, so she does not have to misbehave to get your attention.</li><li><strong>Change the setup.</strong> Repeated trouble often means too much freedom, too much excitement, an unmet toilet/sleep need, or a task that is too hard. Adjust the environment and practice later at an easier level.</li></ol><div class="boundary-examples"><h3>In the moment</h3><dl><dt>Teeth on hands</dt><dd>Pause play and offer a suitable toy. If she keeps biting, step behind a gate briefly for a calm reset; check whether she needs sleep or a toilet trip.</dd><dt>Chewing a shoe</dt><dd>Trade for a treat or suitable toy, then put shoes away. Reward choosing her own chew next time.</dd><dt>Jumping up</dt><dd>Pause attention while she jumps. Offer attention and rewards when her paws return to the floor; use a gate for exciting arrivals.</dd><dt>Pestering her sister</dt><dd>Redirect Clover and separate with a gate before tension builds. Protect your older dog’s quiet space and never make her tolerate pestering.</dd><dt>Barking or growling</dt><dd>Check what is causing it. Add distance or remove the trigger; don’t punish warning signals. Fear, pain or guarding needs a different plan from attention-seeking.</dd><dt>A dangerous object</dt><dd>Keep her safe first; trade if safe to do so and avoid chasing or forcing her mouth open. Suspected swallowing, poison exposure, pain or injury warrants prompt veterinary advice.</dd></dl></div><p class="muted">Don’t ignore fear, pain, distress or unsafe behaviour. For repeated guarding, aggression or separation distress, speak with your vet and a qualified reward-based behaviour professional.</p><p><a href="https://avsab.org/what-are-reward-based-training-methods-for-dogs-and-cats/" target="_blank" rel="noopener">AVSAB: reward-based training & humane management ↗</a></p>${returnSkill?'<button id="backskill">← Back to practice</button>':''}`);if(returnSkill)$('#backskill').onclick=()=>skillView(returnSkill)}
async function memoryView(m){
 modal(`${m.title?`<h2>${esc(m.title)}</h2>`:''}<p class="memory-event-date">${m.date?dt(m.date).toLocaleDateString('en-CA',{month:'long',day:'numeric',year:'numeric'}):'No memory date'}</p><div class="memory-detail"></div>${m.note?`<p class="memory-full-note">${esc(m.note)}</p>`:''}<small>${addedLabel(m)}</small><div class="memory-detail-actions"><button id="edit-open-memory">Edit</button><button id="delete-open-memory">Delete</button></div>`);
 $('#edit-open-memory').onclick=()=>editMemory(m.id);
 $('#delete-open-memory').onclick=()=>form('Delete this memory?','<p>This removes the memory and its attached media.</p>',async()=>{if(m.file)await mediaDelete(m.file);await put(m.id,null,true)});
 if(!m.file)return;
 try{let blob=await mediaGet(m.file),url=URL.createObjectURL(blob),el=document.createElement(blob.type.startsWith('video')?'video':'img');el.src=url;el.alt=memoryLabel(m);if(el.tagName==='VIDEO'){el.controls=true;el.playsInline=true;$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true})}else el.onload=()=>URL.revokeObjectURL(url);$('.memory-detail')?.append(el)}catch(e){toast('Could not open memory: '+e.message)}
}
function displayTime(time){if(!time)return '';let[h,m]=time.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')}${h<12?'am':'pm'}`}
function weekStrip(){let selected=dt(day);return Array.from({length:7},(_,i)=>{let d=new Date(selected);d.setDate(d.getDate()+i-3);let key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return `<button data-day="${key}" class="${key===day?'selected':''} ${key===today()?'is-today':''}" aria-label="${d.toLocaleDateString('en-CA',{weekday:'long',month:'long',day:'numeric'})}" aria-pressed="${key===day}"><span>${d.toLocaleDateString('en-CA',{weekday:'short'})}</span><strong>${d.getDate()}</strong>${key===today()?'<i></i>':''}</button>`}).join('')}
function dayRail(ts,done){let until=Math.round((dt(profile().home)-dt(day))/86400000),focus=day>=profile().home?trainingPlan()[0]:null;return `<div class="rail-sticker"><img src="clover-logo.png" alt="Clover logo"></div><section class="rail-note"><span class="eyebrow">${until>0?'HOME / '+profile().home:'CHECKLIST'}</span><div class="rail-number">${until>0?until:done}<small>${until>0?'days to go':'of '+ts.length+' done'}</small></div></section>${focus?`<section class="rail-focus"><span class="eyebrow">TRAINING FOCUS</span><h3>${focus.title.split(' · ')[0]}</h3><p>${focus.reason}</p><button data-skill="${focus.id}">View practice ↗</button></section>`:'<section class="rail-focus"><span class="eyebrow">SETUP / 3 SPACES</span><h3>Bedroom.<br>Downstairs.<br>Bedtime.</h3><p>Supervised room access. Downstairs pen with an open crate. Sleeping in your bed.</p></section>'}`}
function calendarDates(){let d=dt(day),start=new Date(d);start.setDate(d.getDate()-((d.getDay()+6)%7));return Array.from({length:7},(_,i)=>{let x=new Date(start);x.setDate(start.getDate()+i);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`})}
function tasksOn(date){let previous=day;try{day=date;return tasks()}finally{day=previous}}
function currentTaskOn(date,items){let previous=day;try{day=date;return currentTask(items)}finally{day=previous}}
function taskType(t){if(t.id.startsWith('train-'))return 'training';if(/food|breakfast|lunch|dinner/i.test(t.title))return 'meal';if(/rest|bedtime|settle|pen time/i.test(t.title))return 'rest';if(t.skill)return 'practice';return 'care'}
function weekCalendar(){let dates=calendarDates(),before=dates.every(x=>x<profile().home);return `<div class="calendar-caption"><span>${before?'PREPARATION / choose a day to view its checklist':'WEEK PLAN / click a block for notes & practice'}</span><span>${dt(dates[0]).toLocaleDateString('en-CA',{month:'short',day:'numeric'})} — ${dt(dates[6]).toLocaleDateString('en-CA',{month:'short',day:'numeric'})}</span></div><div class="calendar-scroll"><div class="calendar-board ${before?'prep-board':''}"><div class="calendar-head"><span></span>${dates.map(date=>`<button data-day="${date}" class="${date===day?'selected':''}"><span>${dt(date).toLocaleDateString('en-CA',{weekday:'short'})}</span><strong>${dt(date).getDate()}</strong></button>`).join('')}</div><div class="calendar-body"><div class="time-axis">${before?'<span>PREP</span>':Array.from({length:16},(_,i)=>`<span style="top:${i*80}px">${String(i+7).padStart(2,'0')}:00</span>`).join('')}</div>${dates.map(date=>{let tasks=tasksOn(date);if(date<profile().home)return `<div class="calendar-column prep-column"><p class="prep-shared">${tasks.length} shared prep items.<br>Not timed appointments.</p>${tasks.slice(0,3).map(t=>`<button class="prep-event" data-eventdate="${date}" data-event="${t.id}">${esc(t.title)}</button>`).join('')}<button class="prep-open" data-prepday="${date}">Open checklist ↗</button></div>`;let prevEnd=-1,lane=0;return `<div class="calendar-column">${tasks.filter(t=>t.time).map(t=>{let [h,m]=t.time.split(':').map(Number),mins=h*60+m;if(mins<420||mins>1380)return '';lane=mins<prevEnd?1-lane:0;let overlap=tasks.some(o=>o.id!==t.id&&o.time&&Math.abs((Number(o.time.slice(0,2))*60+Number(o.time.slice(3)))-mins)<35);prevEnd=mins+35;return `<button class="calendar-event type-${taskType(t)} ${date===today()&&currentTaskOn(date,tasks)===t.id?'current':''}" style="top:${(mins-420)*80/60}px;left:${overlap?lane*50:0}%;width:${overlap?'49':'98'}%" data-eventdate="${date}" data-event="${t.id}" title="${esc(t.time+' '+t.title+' — '+t.notes)}"><time>${displayTime(t.time)}</time><span>${esc(t.title.split(' · ')[0])}</span></button>`}).join('')}</div>`}).join('')}</div></div></div><div class="calendar-legend"><span class="type-meal">Meals</span><span class="type-rest">Rest / settling</span><span class="type-training">Training</span><span class="type-practice">Care / practice</span></div><p class="calendar-footnote">Blocks mark start times; their height does not prescribe duration. Toilet breaks remain flexible. Future training uses the progress currently recorded.</p>`}
function calendarDetail(date,id){let t=tasksOn(date).find(x=>x.id===id);if(!t)return;modal(`<span class="eyebrow">${esc(date)} ${esc(t.time)}</span><h2>${esc(t.title)}</h2><p>${esc(t.notes)}</p><p><button id="calendar-open-day">Open this day ↗</button>${t.skill?' <button id="calendar-skill" class="primary">Practice guide ↗</button>':''}${t.careId?' <button id="calendar-care">Reschedule</button> <button id="calendar-care-done">Complete</button>':''}</p>`);$('#calendar-open-day').onclick=()=>{day=date;scheduleView='day';localStorage.setItem('clover-schedule-view-v2','day');$('#modal').close();render()};if(t.careId){$('#calendar-care').onclick=()=>postponeCare(t.careId);$('#calendar-care-done').onclick=()=>completeCare(t.careId)}if(t.skill)$('#calendar-skill').onclick=()=>{day=date;skillView(t.skill)}}


function landingMarkup(){return `<section class="landing" aria-label="Clover photo collage"><div class="landing-stack" id="landing-stack"></div><div class="landing-controls"><button id="add-landing-photos">+ Add photos</button><button id="manage-landing">Manage photos</button><a href="#daily-schedule" id="to-schedule">Daily schedule ↓</a></div></section>`}
async function hydrateLanding(){landingUrls.forEach(u=>URL.revokeObjectURL(u));landingUrls=[];let host=$('#landing-stack');if(!host)return;let items=list('memory:').filter(m=>m.file&&m.featured!==false&&(!m.mime||m.mime.startsWith('image/'))).sort((a,b)=>(b.addedAt||0)-(a.addedAt||0)).slice(0,18),photos=[];host.setAttribute('aria-busy','true');for(let m of items){try{let b=await mediaGet(m.file);if(b.type.startsWith('image/'))photos.push({m,b})}catch(e){toast('Some collage photos could not load. Check your connection.')}}if(!host.isConnected)return;host.removeAttribute('aria-busy');if(!photos.length){host.classList.add('is-empty');host.innerHTML='<div class="empty-photo-outline outline-one"></div><div class="empty-photo-outline outline-two"></div><div class="landing-empty-copy"><h1>clover</h1><p>Add your photos to start the collage.</p></div>';return}host.classList.remove('is-empty');let positions=[[2,11,-8],[19,18,6],[38,7,-5],[57,16,7],[76,10,-3],[7,40,3],[27,37,-7],[48,42,4],[69,39,-6],[1,66,-3],[21,63,7],[42,68,-4],[63,64,6],[78,65,-5],[12,25,-6],[34,28,5],[54,27,-4],[73,28,6]];photos.forEach(({m,b},i)=>{let [x,y,r]=positions[i],button=document.createElement('button'),img=document.createElement('img');button.className='stack-photo';button.style.cssText=`--photo-x:${x}%;--photo-y:${y}%;--photo-angle:${r}deg;--photo-z:${i+1}`;button.setAttribute('aria-label','Open '+memoryLabel(m));button.title=memoryLabel(m);let url=URL.createObjectURL(b);landingUrls.push(url);img.src=url;img.alt=memoryLabel(m);img.draggable=false;button.append(img);button.onclick=()=>memoryView(m);host.append(button)})}
function addedLabel(m){return m.addedAt?'Added '+new Date(m.addedAt).toLocaleDateString('en-CA',{year:'numeric',month:'short',day:'numeric'}):'Added date unavailable · older entry'}
function addMemoryForm(home){form(home?'Add photos':'Add memory',input('date','Memory date (optional)','','date')+input('title','Title (optional)')+input('note','Notes')+`<label for="memory-file">${home?'Photos':'Photos or videos'} · up to 40 MB each</label><input id="memory-file" type="file" name="file" accept="${home?'image/*':'image/*,video/*'}" multiple ${home?'required':''}><label><input class="inlinecheck" type="checkbox" name="featured" checked> Show photos on the home collage</label><p class="muted">Choose Photo Library on your phone. Videos stay in Memories. One entry is created per file.</p>`,async f=>{let files=f.getAll('file').filter(x=>x.size);if(home&&!files.length)throw Error('Choose at least one photo.');if(files.some(x=>x.size>40*1024*1024))throw Error('Choose files under 40 MB each.');if(home&&files.some(x=>x.type&&!x.type.startsWith('image/')))throw Error('Choose photos for the collage.');if(!files.length&&!String(f.get('note')||'').trim()&&!String(f.get('title')||'').trim())throw Error('Add a photo, video or note.');if(!files.length)files=[null];for(let file of files){let path=null;if(file){path=uid();await mediaPut(path,file)}await put('memory:'+uid(),{date:f.get('date'),title:f.get('title'),note:f.get('note'),file:path,mime:file?.type||'',addedAt:Date.now(),featured:f.has('featured')})}})}
function editMemory(id){let m=get(id);form('Edit memory',input('date','Memory date (optional)',m.date||'','date')+input('title','Title (optional)',m.title||'')+input('note','Notes',m.note)+`<label><input class="inlinecheck" type="checkbox" name="featured" ${m.featured!==false?'checked':''}> Show photo on the home collage</label><p class="muted">${addedLabel(m)}. Unchecking this keeps the photo in Memories.</p>`,async f=>put(id,{...m,date:f.get('date'),title:f.get('title'),note:f.get('note'),featured:f.has('featured')}))}

function careTasks(){let due=list('care:').filter(x=>x.next&&(x.next===day||(day===today()&&x.next<day))).map(x=>({id:x.id,careId:x.id,time:x.time||'18:00',title:x.title,notes:`${x.kind} · ${x.next<day?'Overdue from '+x.next+'. ':''}${x.notes||''}`,skill:''}));let completed=list('carelog:').filter(x=>x.date===day).map(x=>({...x,time:x.time||'18:00',notes:'Completed · '+(x.notes||''),skill:'',completed:true}));return [...due,...completed]}
function postponeCare(id){let x=get(id);form('Reschedule '+esc(x.title),input('next','New date',x.next||day,'date',true)+input('time','Time',x.time||'18:00','time',true)+input('reason','Note (optional)'),async f=>put(id,{...x,next:f.get('next'),time:f.get('time'),moves:[...(x.moves||[]),{from:x.next,to:f.get('next'),at:Date.now(),note:f.get('reason')}]}))}
function completeCare(id){let x=get(id),next='';if(Number(x.interval)>0){let d=dt(day);d.setDate(d.getDate()+Number(x.interval));next=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}form('Complete '+esc(x.title),input('date','Completed date',day,'date',true)+input('next','Next due date (optional)',next,'date')+input('notes','Completion notes',x.notes||''),async f=>{await put('carelog:'+uid(),{careRecord:id,title:x.title,date:f.get('date'),time:x.time||'18:00',notes:f.get('notes')});await put(id,{...x,date:f.get('date'),next:f.get('next')});toast('Care recorded. The next date is on your schedule.')})}
function scheduleCare(){form('Schedule care',`<label>Type</label><select name="kind"><option>Bath</option><option>Grooming appointment</option><option>Vet</option><option>Vaccine</option><option>Medication review</option><option>Parasite prevention</option><option>Other</option></select>`+input('title','Task name','','text',true)+input('next','Date',day,'date',true)+input('time','Time','18:00','time',true)+input('interval','Repeat every N days (optional)','','number')+input('notes','Notes / instructions')+'<p class="muted">Choose bathing and grooming timing with your groomer or vet. Use their confirmed dates for vaccines and medications.</p>',async f=>{let v=Object.fromEntries(f);if(v.interval&&(Number(v.interval)<1||!Number.isInteger(Number(v.interval))))throw Error('Use a whole number of days.');await put('care:'+uid(),v)})}

function memoryLabel(m){return m.title?.trim()||'Memory'}
function albumDate(m){return m.date|| (m.addedAt?new Date(m.addedAt).getFullYear()+'-'+String(new Date(m.addedAt).getMonth()+1).padStart(2,'0')+'-'+String(new Date(m.addedAt).getDate()).padStart(2,'0'):'')}
function albumMonth(m){return albumDate(m).slice(0,7)||'undated'}
function renderAlbum(){
 const app=$('#app');app.innerHTML=`<h1>memories</h1><div class="toolbar album-toolbar"><button id="memory" class="primary">+ Add memory</button><input id="memorydate" type="date" aria-label="Filter memory date"><button id="clearfilter">Show all</button></div><div id="album" class="album"></div>`;
 const paint=async()=>{
 const target=$('#album'),filter=$('#memorydate').value;
 let items=list('memory:').filter(m=>!filter||albumDate(m)===filter).sort((a,b)=>albumDate(b).localeCompare(albumDate(a))||(b.addedAt||0)-(a.addedAt||0)),groups=new Map();
 for(let m of items){let key=albumDate(m)||'undated';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(m)}
 target.innerHTML=items.length?[...groups].map(([key,entries])=>`<section class="photo-date-group"><div class="photo-date-heading"><h2>${key==='undated'?'Undated':dt(key).toLocaleDateString('en-CA',{month:'long',day:'numeric',year:'numeric'})}</h2><small>${entries.length} ${entries.length===1?'memory':'memories'}</small></div><div class="photo-grid">${entries.map(m=>`<button class="photo-tile" data-open-memory="${m.id}" aria-label="Open ${esc(memoryLabel(m))}">${m.file?'':`<span class="note-thumbnail">${esc(m.note||m.title||'Memory')}</span>`}</button>`).join('')}</div></section>`).join(''):'<p class="album-empty">Add photos, videos or notes to start your album.</p>';
 target.querySelectorAll('[data-open-memory]').forEach(button=>button.onclick=()=>memoryView(items.find(m=>m.id===button.dataset.openMemory)));
 for(let m of items){if(!m.file)continue;try{let blob=await mediaGet(m.file);if(!target.isConnected)return;let tile=[...target.querySelectorAll('[data-open-memory]')].find(e=>e.dataset.openMemory===m.id);if(!tile)continue;let url=URL.createObjectURL(blob),video=blob.type.startsWith('video'),el=document.createElement(video?'video':'img');el.alt=memoryLabel(m);el.src=url;if(video){el.muted=true;el.playsInline=true;el.preload='metadata';let badge=document.createElement('span');badge.className='video-badge';badge.textContent='Video';tile.append(badge);el.onloadedmetadata=()=>{if(Number.isFinite(el.duration))badge.textContent=Math.floor(el.duration/60)+':'+String(Math.floor(el.duration%60)).padStart(2,'0')};window.addEventListener('hashchange',()=>URL.revokeObjectURL(url),{once:true})}else{el.loading='lazy';el.onload=()=>URL.revokeObjectURL(url)}tile.prepend(el)}catch(e){toast('Could not load memory: '+e.message)}}
 };$('#memory').onclick=()=>addMemoryForm(false);$('#memorydate').onchange=paint;$('#clearfilter').onclick=()=>{$('#memorydate').value='';paint()};paint()
}
window.addEventListener('hashchange',render);window.addEventListener('focus',async()=>{await sync();render()});setInterval(async()=>{await sync()},30000);render();try{await connect();render()}catch(e){toast('Local mode: '+e.message)}document.querySelector('#loading')?.remove();
